96	inline void *GetOpApiFuncAddrInLib(void *handler, const char *libName, const char *apiName)
97	{
98	    auto funcAddr = dlsym(handler, apiName);
99	    if (funcAddr == nullptr) {
100	        OP_LOGW("aclnnfallback", "dlsym %s from %s failed, error:%s.", apiName, libName, dlerror());
101	    }
102	    return funcAddr;
103	}
