105	inline void *GetOpApiLibHandler(const char *libName)
106	{
107	    auto handler = dlopen(libName, RTLD_LAZY);
108	    if (handler == nullptr) {
109	        OP_LOGW("aclnnfallback", "dlopen %s failed, error:%s.", libName, dlerror());
110	    }
111	    return handler;
112	}
