114	inline void *GetAclnnArrdByApiName(const char *apiName)
115	{
116	    vector<std::string> libs = {"libaclnn_ops_infer.so", "libaclnn_ops_train.so", "libaclnn_math.so",
117	                                "libaclnn_rand.so",      "libaclnn_sparse.so",    "libaclnn_fft.so"};
118	    for (const auto &libName : libs) {
119	        static auto libHandler = GetOpApiLibHandler(libName.c_str());
120	        if (libHandler != nullptr) {
121	            auto funcAddr = GetOpApiFuncAddrInLib(libHandler, libName.c_str(), apiName);
122	            if (funcAddr != nullptr) {
123	                return funcAddr;
124	            }
125	        }
126	    }
127	    OP_LOGE("aclnnfallback", "api %s can't find in any aclnn lib.", apiName);
128	    return nullptr;
129	}
