131	inline void *GetOpApiFuncAddr(const char *apiName)
132	{
133	    static auto custOpApiHandler = GetOpApiLibHandler(GetCustOpApiLibName());
134	    if (custOpApiHandler != nullptr) {
135	        auto funcAddr = GetOpApiFuncAddrInLib(custOpApiHandler, GetCustOpApiLibName(), apiName);
136	        if (funcAddr != nullptr) {
137	            return funcAddr;
138	        }
139	    }
140	
141	    static auto transformerOpApiHandler = GetOpApiLibHandler(GetTransformerOpApiLibName());
142	    if (transformerOpApiHandler != nullptr) {
143	        auto funcAddr = GetOpApiFuncAddrInLib(transformerOpApiHandler, GetTransformerOpApiLibName(), apiName);
144	        if (funcAddr != nullptr) {
145	            return funcAddr;
146	        }
147	    }
148	
149	    static auto opApiHandler = GetOpApiLibHandler(GetOpApiLibName());
150	    if (opApiHandler != nullptr) {
151	        auto funcAddr = GetOpApiFuncAddrInLib(opApiHandler, GetOpApiLibName(), apiName);
152	        if (funcAddr != nullptr) {
153	            return funcAddr;
154	        }
155	    }
156	    OP_LOGD("aclnnfallback", "opapi lib is not exist,will use aclnn lib.");
157	    return GetAclnnArrdByApiName(apiName);
158	}
