175	inline aclDataType GetConvertType(const gert::Tensor *geTensor)
176	{
177	    static unordered_map<ge::DataType, aclDataType> dataTypeMap = {{DT_FLOAT, aclDataType::ACL_FLOAT},
178	                                                                   {DT_BF16, aclDataType::ACL_BF16},
179	                                                                   {DT_BOOL, aclDataType::ACL_BOOL},
180	                                                                   {DT_INT64, aclDataType::ACL_INT64},
181	                                                                   {DT_UINT64, aclDataType::ACL_UINT64},
182	                                                                   {DT_INT32, aclDataType::ACL_INT32},
183	                                                                   {DT_UINT32, aclDataType::ACL_UINT32},
184	                                                                   {DT_INT8, aclDataType::ACL_INT8},
185	                                                                   {DT_UINT8, aclDataType::ACL_UINT8},
186	                                                                   {DT_INT4, aclDataType::ACL_INT4},
187	                                                                   {DT_FLOAT8_E4M3FN, aclDataType::ACL_FLOAT8_E4M3FN},
188	                                                                   {DT_FLOAT8_E5M2, aclDataType::ACL_FLOAT8_E5M2},
189	                                                                   {DT_FLOAT4_E2M1, aclDataType::ACL_FLOAT4_E2M1},
190	                                                                   {DT_FLOAT4_E1M2, aclDataType::ACL_FLOAT4_E1M2},
191	                                                                   {DT_FLOAT8_E8M0, aclDataType::ACL_FLOAT8_E8M0},
192	                                                                   {DT_HIFLOAT8, aclDataType::ACL_HIFLOAT8}};
193	    // convert data type
194	    auto dataTypeGe = geTensor->GetDataType();
195	    auto dataTypeIter = dataTypeMap.find(dataTypeGe);
196	    if (dataTypeIter != dataTypeMap.end()) {
197	        return dataTypeIter->second;
198	    }
199	    return aclDataType::ACL_FLOAT16;
200	}
