202	inline aclTensor *ConvertType(const gert::Tensor *ge_tensor)
203	{
204	    if (ge_tensor == nullptr) {
205	        return nullptr;
206	    }
207	
208	    static const auto aclCreateTensor = GET_OP_API_FUNC(aclCreateTensor);
209	    OP_CHECK_IF(aclCreateTensor == nullptr, OP_LOGE("aclnnfallback", "aclCreateTensor nullptr"), return nullptr);
210	
211	    void *device_addr = nullptr;
212	    device_addr = const_cast<void *>(ge_tensor->GetAddr());
213	
214	    auto dataType = GetConvertType(ge_tensor);
215	
216	    OP_LOGD("aclnnfallback", "aclCreateTensor: tensor type is %d", dataType);
217	
218	    // convert shape
219	    auto gert_shape = ge_tensor->GetStorageShape();
220	    std::vector<int64_t> shape;
221	    for (size_t i = 0; i < gert_shape.GetDimNum(); ++i) {
222	        shape.push_back(gert_shape.GetDim(i));
223	    }
224	
225	    // 计算连续tensor的strides
226	    std::vector<int64_t> strides(shape.size(), 1);
227	    for (int64_t i = shape.size() - 2; i >= 0; i--) {
228	        strides[i] = shape[i + 1] * strides[i + 1];
229	    }
230	
231	    aclTensor *out = aclCreateTensor(shape.data(), shape.size(), dataType, strides.data(), 0, aclFormat::ACL_FORMAT_ND,
232	                                     shape.data(), shape.size(), device_addr);
233	
234	    OP_CHECK_IF(out == nullptr, OP_LOGE("aclnnfallback", "out nullptr"), return nullptr);
235	
236	    return out;
237	}
