247	    for (size_t i = 0; i < ge_tenserList.size(); i++) {
248	        auto t_acl = ConvertType(ge_tenserList[i]);
249	        tmp.push_back(t_acl);
250	    }
251	
252	    aclTensorList *tensorList = aclCreateTensorList(tmp.data(), tmp.size());
253	    return tensorList;
254	}
