273	inline aclTensor *ConvertMmType(const gert::Tensor *ge_tensor, bool transpose, bool enable_NZ = false)
274	{
275	    if (ge_tensor == nullptr) {
276	        return nullptr;
277	    }
278	    auto gert_shape = ge_tensor->GetStorageShape();
279	    if (gert_shape.GetDimNum() <= 1) {
280	        return ConvertType(ge_tensor);
281	    }
282	
283	    static const auto aclCreateTensor = GET_OP_API_FUNC(aclCreateTensor);
284	    OP_CHECK_IF(aclCreateTensor == nullptr, OP_LOGE("aclnnfallback", "aclCreateTensor nullptr"), return nullptr);
285	
286	    void *device_addr = const_cast<void *>(ge_tensor->GetAddr());
287	    // convert data type
288	    auto dataType_ge = ge_tensor->GetDataType();
289	    auto dataType = ToAclDataType(dataType_ge);
290	    // convert shape
291	    std::vector<int64_t> shape;
292	    for (size_t i = 0; i < gert_shape.GetDimNum(); ++i) {
293	        shape.push_back(gert_shape.GetDim(i));
294	    }
295	    // 计算连续tensor的strides
296	    std::vector<int64_t> strides(shape.size(), 1);
297	    for (int64_t i = shape.size() - 2; i >= 0; i--) {
298	        strides[i] = shape[i + 1] * strides[i + 1];
299	    }
300	
301	    auto viewShape = shape;
302	    // 对于transpose后的tensor对后两维度进行strides, viewShape转换
303	    if (transpose) {
304	        // dimM 为倒数第二维， dimN 为倒数第一维度
305	        auto dimM = shape.size() - 2;
306	        auto dimN = shape.size() - 1;
307	        auto swap = strides[dimN];
308	        strides[dimN] = strides[dimM];
309	        strides[dimM] = swap;
310	        // 修改viewShape
311	        viewShape[dimN] = shape[dimM];
312	        viewShape[dimM] = shape[dimN];
313	    }
314	    auto acl_format = aclFormat::ACL_FORMAT_ND;
315	    if (enable_NZ && GetPrimaryFormat(ge_tensor->GetStorageFormat()) == ge::Format::FORMAT_FRACTAL_NZ) {
316	        acl_format = aclFormat::ACL_FORMAT_FRACTAL_NZ;
317	    }
318	    aclTensor *out = aclCreateTensor(viewShape.data(), shape.size(), dataType, strides.data(), 0, acl_format,
319	                                     shape.data(), shape.size(), device_addr);
320	    OP_CHECK_IF(out == nullptr, OP_LOGE("aclnnfallback", "out nullptr"), return nullptr);
321	
322	    return out;
323	}
