399	template <typename Tuple, size_t... I>
400	auto ConvertToOpApiFunc(const Tuple &params, void *opApiAddr, std_utils::index_sequence<I...>)
401	    -> int (*)(typename std::decay<decltype(std::get<I>(params))>::type...)
402	{
403	    using LocalOpApiFunc = int (*)(typename std::decay<decltype(std::get<I>(params))>::type...);
404	    auto func = reinterpret_cast<LocalOpApiFunc>(opApiAddr);
405	    return func;
406	}
407	
408	template <typename Tuple>
409	auto ConvertToOpApiFunc(const Tuple &params, void *opApiAddr) ->
410	    typename std::enable_if<
411	        std::tuple_size<Tuple>::value != 0,
412	        decltype(ConvertToOpApiFunc(params, opApiAddr,
413	                                    std_utils::make_index_sequence<std::tuple_size<Tuple>::value>{}))>::type
414	{
415	    static constexpr auto size = std::tuple_size<Tuple>::value;
416	    return ConvertToOpApiFunc(params, opApiAddr, std_utils::make_index_sequence<size>{});
417	}
418	
419	template <typename Tuple>
420	class ConvertedParams {
421	public:
422	    ConvertedParams(Tuple &&convertedParams) : convertedParams_(std::move(convertedParams)) {};
423	    ConvertedParams(ConvertedParams &&other) : convertedParams_(std::move(other.convertedParams_))
424	    {
425	        other.validParams_ = false;
426	    };
427	    ConvertedParams &operator=(ConvertedParams &&other)
428	    {
429	        if (this == &other) {
430	            return *this;
431	        }
432	
433	        convertedParams_ = std::move(other.convertedParams_);
434	        validParams_ = true;
435	        other.validParams_ = false;
436	        return *this;
437	    }
438	
439	    ConvertedParams() = delete;
440	    ConvertedParams(const ConvertedParams &other) = delete;
441	    ConvertedParams &operator=(const ConvertedParams &other) = delete;
442	
443	    ~ConvertedParams()
444	    {
445	        if (validParams_) {
446	            ReleaseConvertTypes(convertedParams_);
447	        }
448	    }
449	
450	    const Tuple &GetConvertedParams() const
451	    {
452	        return convertedParams_;
453	    }
454	
455	private:
456	    Tuple convertedParams_;
457	    bool validParams_{true};
458	};
