474	            static const auto ResetCacheThreadLocalAddr = GetOpApiFuncAddr("ResetCacheThreadLocal");                   \
475	            static const auto getWorkspaceSizeFuncAddr = GetOpApiFuncAddr(#aclnn_api "GetWorkspaceSize");              \
476	            static const auto opApiFuncAddr = GetOpApiFuncAddr(#aclnn_api);                                            \
477	            if (getWorkspaceSizeFuncAddr == nullptr || opApiFuncAddr == nullptr ||                                     \
478	                ResetCacheThreadLocalAddr == nullptr) {                                                                \
479	                OP_LOGE("aclnnfallback", "%s or %s not in %s or %s or %s or ResetCacheThreadLocal not found.",         \
480	                        #aclnn_api "GetWorkspaceSize", #aclnn_api, GetCustOpApiLibName(),                              \
481	                        GetTransformerOpApiLibName(), GetOpApiLibName());                                              \
482	                ret = GRAPH_FAILED;                                                                                    \
483	                break;                                                                                                 \
484	            }                                                                                                          \
485	            auto ResetCacheThreadLocalFunc = reinterpret_cast<ResetCacheThreadLocal>(ResetCacheThreadLocalAddr);       \
486	            ResetCacheThreadLocalFunc();                                                                               \
487	            uint64_t workspace_size = 0;                                                                               \
488	            uint64_t *workspace_size_addr = &workspace_size;                                                           \
489	            aclOpExecutor *executor = nullptr;                                                                         \
490	            aclOpExecutor **executor_addr = &executor;                                                                 \
491	            auto converted_params = ConvertTypes(__VA_ARGS__, workspace_size_addr, executor_addr);                     \
492	            static auto getWorkspaceSizeFunc = ConvertToOpApiFunc(converted_params, getWorkspaceSizeFuncAddr);         \
493	            auto workspace_status = call(getWorkspaceSizeFunc, converted_params);                                      \
494	            if (workspace_status != 0) {                                                                               \
495	                OP_LOGE("aclnnfallback", "call %s failed:", #aclnn_api);                                               \
496	                ret = GRAPH_FAILED;                                                                                    \
497	                break;                                                                                                 \
498	            }                                                                                                          \
499	            void *workspace_addr = nullptr;                                                                            \
500	            if (workspace_size > 0) {                                                                                  \
501	                workspace_addr = host_api_ctx->MallocWorkspace(workspace_size);                                        \
502	                if (workspace_addr == nullptr) {                                                                       \
503	                    OP_LOGE("aclnnfallback", "call %s allocate workspace failed", #aclnn_api);                         \
504	                    ret = GRAPH_FAILED;                                                                                \
505	                    break;                                                                                             \
506	                }                                                                                                      \
507	            }                                                                                                          \
508	            auto acl_stream = host_api_ctx->GetStream();                                                               \
509	            auto acl_call = [converted_params, workspace_addr, workspace_size, host_api_ctx, acl_stream,               \
510	                             executor]() -> int {                                                                      \
511	                using OpApiFunc = int (*)(void *, uint64_t, aclOpExecutor *, const aclrtStream);                       \
512	                OpApiFunc opApiFunc = reinterpret_cast<OpApiFunc>(opApiFuncAddr);                                      \
513	                auto api_ret_inner = opApiFunc(workspace_addr, workspace_size, executor, acl_stream);                  \
514	                ReleaseConvertTypes(converted_params);                                                                 \
515	                host_api_ctx->FreeWorkspace();                                                                         \
516	                if (api_ret_inner != 0) {                                                                              \
517	                    OP_LOGE("aclnnfallback", "call %s allocate workspace failed api_ret_inner: %d", #aclnn_api,        \
518	                            api_ret_inner);                                                                            \
519	                    return GRAPH_FAILED;                                                                               \
520	                }                                                                                                      \
521	                return api_ret_inner;                                                                                  \
522	            };                                                                                                         \
523	                                                                                                                       \
524	            ret = acl_call();                                                                                          \
525	        } while (false);                                                                                               \
526	        (ret);                                                                                                         \
527	    })
528	
529	} // namespace fallback
530	
531	#endif //  ACLNNFALLBACK_OPAPI_H_
