21	
22	struct MatmulParas {
23	    /* const aclTensor *会导致Release重载方法匹配不上，造成内存泄漏 */
24	    aclTensor *x1_acl;
25	    aclTensor *x2_acl;
26	    const gert::Tensor *bias;
27	};
28	
29	inline ge::graphStatus GetMatmulPara(const gert::OpExecuteContext *host_api_ctx, size_t x1_idx, size_t x2_idx,
30	                                     size_t bias_idx, MatmulParas &para)
31	{
32	    const auto x1 = host_api_ctx->GetInputTensor(x1_idx);
33	    OPS_CHECK(x1 == nullptr, OP_LOGE_WITH_INVALID_INPUT(host_api_ctx->GetNodeName(), "x1"), return ge::GRAPH_FAILED);
34	
35	    const auto x2 = host_api_ctx->GetInputTensor(x2_idx);
36	    OPS_CHECK(x2 == nullptr, OP_LOGE_WITH_INVALID_INPUT(host_api_ctx->GetNodeName(), "x2"), return ge::GRAPH_FAILED);
37	
38	    para.bias = host_api_ctx->GetOptionalInputTensor(bias_idx);
39	
40	    const auto attrs = host_api_ctx->GetAttrs();
41	    OPS_CHECK(attrs == nullptr, OP_LOGE_WITH_INVALID_INPUT(host_api_ctx->GetNodeName(), "attrs"),
42	              return ge::GRAPH_FAILED);
43	
44	    para.x1_acl = ConvertMmType(x1, false);
45	    OPS_CHECK(para.x1_acl == nullptr, OP_LOGE_WITH_INVALID_INPUT(host_api_ctx->GetNodeName(), "x1_acl"),
